import {createPhotoCache} from './photo-cache.js';
import {normalize,matches,accepts,review,mastered,due,validProgress} from './logic.js';
const $=s=>document.querySelector(s),app=$('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let birds=[],meta={},records={},db,storageOK=true,session=null,theme='system';
// Loaded separately from the taxonomy so media updates cannot overwrite species data.
let photos={};
let lookupPhotos=false,learnPhotos=true;
const studyPhotos=createPhotoCache({baseURL:document.baseURI});
function warmStudyPhotos(x){if(x.photos)studyPhotos.warm(x.queue.slice(x.index,x.index+3).map(item=>photos[item.id]).filter(Boolean));}
function mountStudyPhoto(s){const slot=$('#feedback .study-photo-slot'),p=photos[s.id];if(!slot||!p)return;studyPhotos.get(p).then(image=>{if(!slot.isConnected)return;image.className='species-photo';image.alt=s.de+' ('+s.sci+')';image.width=p.width;image.height=p.height;slot.replaceWith(image);}).catch(()=>{if(!slot.isConnected)return;const figure=slot.closest('.bird-photo');slot.parentElement.hidden=true;figure.querySelector('.photo-error').hidden=false;});}
const gallery=s=>`https://media.ebird.org/catalog?mediaType=photo&taxonCode=${encodeURIComponent(s.id)}`;
const photoFallback=s=>`<p class="photo-fallback">Bild derzeit nicht verfügbar. <a href="${gallery(s)}" target="_blank" rel="noopener noreferrer">eBird-Fotogalerie öffnen ↗</a></p>`;
function photoMarkup(s,study=false){const p=photos[s.id];if(!p)return photoFallback(s);return `<figure class="bird-photo"><a class="photo-original" href="${esc(p.source)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(s.de)}: Originalfoto auf Wikimedia Commons">${study?'<span class="study-photo-slot" role="status" aria-label="Artenbild wird geladen"></span>':`<img class="species-photo" src="${esc(p.local)}" alt="${esc(s.de)} (${esc(s.sci)})" width="${p.width}" height="${p.height}" loading="lazy" decoding="async">`}</a><div class="photo-error" hidden>${photoFallback(s)}</div><figcaption>Foto: ${esc(p.attribution||p.credit)} · <a href="${esc(p.source)}" target="_blank" rel="noopener noreferrer" title="${esc(p.title)}">Wikimedia Commons</a> · <a href="${esc(p.licenseUrl)}" target="_blank" rel="noopener noreferrer">${esc(p.license)}</a><details class="photo-credit"><summary>Bildnachweis</summary><p>${esc(p.title)} · für die Anzeige verkleinert, Inhalt unverändert${p.attribution&&p.attribution!==p.credit?' · Urheber: '+esc(p.credit):''}.</p></details></figcaption></figure>`;}
document.addEventListener('error',event=>{const img=event.target;if(img instanceof HTMLImageElement&&img.classList.contains('species-photo')){const figure=img.closest('.bird-photo');img.parentElement.hidden=true;figure.querySelector('.photo-error').hidden=false;}},true);
const levels=['Grundwortschatz','Erweitert','Spezialwortschatz'];
function studyMode(active){document.body.classList.toggle('studying',active);updateStudyViewport();}
function updateStudyViewport(){const v=window.visualViewport;const inset=v?Math.max(0,window.innerHeight-v.height-v.offsetTop):0;document.documentElement.style.setProperty('--study-keyboard-inset',inset+'px');}
window.visualViewport?.addEventListener('resize',updateStudyViewport);
window.visualViewport?.addEventListener('scroll',updateStudyViewport);
window.addEventListener('resize',updateStudyViewport);

const key=(s,t)=>s.id+':'+t,progress=(s,t)=>records[key(s,t)];
try{theme=localStorage.getItem('birdnames-theme')||'system';}catch{}
function applyTheme(){document.body.classList.toggle('dark',theme==='dark'||(theme==='system'&&matchMedia('(prefers-color-scheme:dark)').matches));const label={system:'Automatisch',light:'Hell',dark:'Dunkel'}[theme];$('#theme').title='Farbschema: '+label;$('#theme').setAttribute('aria-label','Farbschema: '+label+'. Wechseln');}
applyTheme();matchMedia('(prefers-color-scheme:dark)').addEventListener('change',applyTheme);$('#theme').onclick=()=>{theme=theme==='system'?'light':theme==='light'?'dark':'system';applyTheme();try{localStorage.setItem('birdnames-theme',theme)}catch{}};
async function initDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('birdnames-de',1);req.onupgradeneeded=()=>req.result.createObjectStore('state');req.onerror=()=>reject(req.error);req.onsuccess=()=>{db=req.result;const r=db.transaction('state').objectStore('state').get('records');r.onsuccess=()=>{records=r.result||{};resolve()};r.onerror=()=>reject(r.error)}})}
async function save(){if(!db){storageOK=false;return false;}return new Promise(resolve=>{const tx=db.transaction('state','readwrite');tx.objectStore('state').put(records,'records');tx.oncomplete=()=>resolve(true);tx.onerror=()=>{storageOK=false;resolve(false)}})}
function storageNotice(){return storageOK?'':'<p class="notice" role="alert">Der Browser kann den Lernstand gerade nicht dauerhaft speichern. Bitte exportiere ihn vor dem Schließen.</p>';}
const opt=(v,l=v,selected=false)=>`<option value="${esc(v)}"${selected?' selected':''}>${esc(l)}</option>`;
const groups=()=>[...new Set(birds.map(s=>s.group))].sort((a,b)=>a.localeCompare(b,'de'));
function card(s){return `<article class="card"><h3>${esc(s.de)}</h3><p class="english">${esc(s.en)}</p><p class="latin">${esc(s.sci)}</p><p><span class="code">${esc(s.codes[0])}</span><a href="https://ebird.org/species/${s.id}" target="_blank" rel="noopener">eBird ↗<span class="sr">: ${esc(s.de)}</span></a></p>${lookupPhotos?photoMarkup(s):''}<div class="tags">${esc(s.group)} · ${levels[s.level-1]}</div><details><summary>Status & Varianten</summary><p>${esc(s.status.join(' · '))}</p><p>${esc([...s.aliases.de,...s.aliases.en].join(' · ')||'Keine weiteren Namensvarianten hinterlegt.')}</p>${s.codes.length>1?`<p>Weitere offizielle Quick Codes: ${s.codes.slice(1).map(esc).join(', ')}</p>`:''}${s.codeSource==='banding_code'?'<p>Codequelle: Banding-Code-Spalte der offiziellen eBird-Tabelle; kein separater common-name Quick Code eingetragen.</p>':'<p>Codequelle: com_quick_codes der offiziellen eBird-Tabelle.</p>'}${s.note?`<p>${esc(s.note)}</p>`:''}</details></article>`}
function lookup(){app.innerHTML=`<h1 class="sr">Arten nachschlagen</h1><div class="toolbar"><label class="sr" for="search">Vogelname oder Quick Find Code</label><input type="search" id="search" class="search" placeholder="Artname oder vierstelliger Code" autocomplete="off"><label class="sr" for="group">Artengruppe</label><select id="group">${opt('','Alle Artengruppen')+groups().map(g=>opt(g)).join('')}</select><label class="sr" for="level">Lernstufe</label><select id="level">${opt('','Alle Lernstufen')+levels.map((x,i)=>opt(i+1,x)).join('')}</select><label class="photo-option"><input type="checkbox" id="lookup-photos" ${lookupPhotos?'checked':''}>Artenbilder</label></div><div id="results-meta" class="meta" role="status"></div><div id="results" class="grid"></div>`;let update=()=>{let q=$('#search').value,g=$('#group').value,l=$('#level').value;let result=birds.filter(s=>(!g||s.group===g)&&(!l||s.level===+l)&&matches(s,q));$('#results-meta').innerHTML=`<span>${result.length} von ${birds.length} Arten</span><span>Alphabetisch nach deutschem Namen</span>`;$('#results').innerHTML=result.length?result.map(card).join(''):'<p>Keine passende Art. Versuche einen kürzeren Namen oder ändere die Filter.</p>';};['search','group','level'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',update));$('#lookup-photos').onchange=e=>{lookupPhotos=e.target.checked;update()};update();}
function learn(){if(session){renderQuestion();return;}studyMode(false);app.innerHTML=`<h1>Lerneinheit</h1>${storageNotice()}<form id="setup" class="panel"><div class="settings"><div class="field"><label for="target">Lernziel</label><select id="target">${opt('en','Englische Namen')+opt('code','Quick Find Codes')+opt('mixed','Gemischt, abwechselnd')}</select></div><div class="field"><label for="method">Antwortmethode</label><select id="method">${opt('text','Aktive Texteingabe')+opt('flash','Karteikarten')+opt('mc','Multiple Choice',true)}</select></div><div class="field"><label for="scope">Lernstand</label><select id="scope">${opt('all','Alle Arten')+opt('unmastered','Noch nicht beherrscht')+opt('due','Nur fällige Wiederholungen')+opt('wrong','Zuletzt falsch beantwortet')}</select></div><div class="field"><label for="count">Fragen pro Einheit</label><select id="count">${[10,15,25].map(n=>opt(n,n+' Fragen')).join('')+opt('all','Alle passenden Arten')}</select></div></div><fieldset><legend>Lernstufen</legend>${levels.map((l,i)=>`<label><input name="levels" type="checkbox" value="${i+1}" ${i===0?'checked':''}>${l}</label>`).join('')}</fieldset><details><summary>Artengruppen auswählen (Standard: alle)</summary><fieldset><legend>Eine oder mehrere Gruppen</legend>${groups().map(g=>`<label><input type="checkbox" name="groups" value="${esc(g)}">${esc(g)}</label>`).join('')}</fieldset></details><label class="photo-option learn-photo-option"><input type="checkbox" id="learn-photos" ${learnPhotos?'checked':''}>Artenbild nach der Antwort anzeigen</label><p class="muted" id="selection-count" role="status"></p><div class="actions"><button class="primary" type="submit">Lerneinheit starten →</button></div><p class="form-note">Englische Namen und Codes haben getrennte Lernstände. Fehler werden in der Einheit wiederholt.</p></form>`;
 const selection=()=>{let ls=[...document.querySelectorAll('[name=levels]:checked')].map(x=>+x.value),gs=[...document.querySelectorAll('[name=groups]:checked')].map(x=>x.value),target=$('#target').value,scope=$('#scope').value;let ts=target==='mixed'?['en','code']:[target];let eligible=(s,t)=>scope==='all'||scope==='unmastered'&&!mastered(progress(s,t))||scope==='due'&&due(progress(s,t))||scope==='wrong'&&progress(s,t)?.lastWrong;let pool=birds.filter(s=>ls.includes(s.level)&&(!gs.length||gs.includes(s.group))&&ts.some(t=>eligible(s,t)));return {pool,eligible,target};};
 const update=()=>{$('#selection-count').textContent=selection().pool.length+' Arten passen zur Auswahl.';};$('#setup').onchange=update;update();$('#setup').onsubmit=e=>{e.preventDefault();let {pool,eligible,target}=selection();if(!pool.length){$('#selection-count').textContent='Keine passenden Arten. Bitte Auswahl erweitern.';return;}pool=pool.map(s=>({s,r:Math.random()})).sort((a,b)=>{let rank=s=>{let ts=target==='mixed'?['en','code']:[target];return Math.min(...ts.filter(t=>eligible(s,t)).map(t=>{let p=progress(s,t);return due(p)?0:!p?1:p.lastWrong?2:3}))};return rank(a.s)-rank(b.s)||a.r-b.r}).map(x=>x.s);let n=$('#count').value==='all'?pool.length:Math.min(+$('#count').value,pool.length);let queue=pool.slice(0,n).map((s,i)=>{let t=target==='mixed'?(i%2?'code':'en'):target;if(!eligible(s,t))t=t==='en'?'code':'en';return {id:s.id,t,retry:0}});learnPhotos=$('#learn-photos').checked;session={queue,index:0,correct:0,answered:0,method:$('#method').value,photos:learnPhotos,done:false,hint:false};renderQuestion();};}
function renderQuestion(){let x=session;studyMode(x.index<x.queue.length);window.scrollTo(0,0);if(x.index>=x.queue.length){app.innerHTML=`<div class="session panel question"><h1>Einheit beendet</h1><p><strong>${x.correct} von ${x.answered}</strong> Antworten richtig.</p>${storageNotice()}<div class="actions"><button id="restart" class="primary">Neue Einheit</button><a href="#statistik">Fortschritt ansehen</a></div></div>`;$('#restart').onclick=()=>{session=null;learn()};return;}
 warmStudyPhotos(x);let item=x.queue[x.index],s=birds.find(s=>s.id===item.id);x.done=false;x.hint=false;let target=item.t==='en'?'Englischer Name':'Quick Find Code';app.innerHTML=`<div class="session"><div class="meta"><span>Frage ${x.index+1} von ${x.queue.length}${item.retry?' · Wiederholung':''}</span><button id="stop" class="quiet">Einheit beenden</button></div><progress value="${x.index}" max="${x.queue.length}" aria-label="Fortschritt der Einheit"></progress><div class="panel question"><div class="eyebrow">Deutsch → ${target}</div><h1>${esc(s.de)}</h1><div id="answer-area"></div><div id="feedback" aria-live="polite"></div></div>${storageNotice()}</div>`;$('#stop').onclick=()=>{session=null;learn()};
 const answerArea=$('#answer-area');if(x.method==='text'){answerArea.innerHTML=`<form id="answer-form"><label class="sr" for="answer">${target}</label><input id="answer" placeholder="${item.t==='code'?'Vier Buchstaben':'Englischen Namen eingeben'}" ${item.t==='code'?'maxlength="4" autocapitalize="characters"':'autocapitalize="off"'} autocomplete="off" autocorrect="off" spellcheck="false"><div class="actions study-actions"><button type="submit" class="primary">Prüfen</button><button type="button" id="hint" class="quiet">Hinweis</button></div><p id="hint-text" class="muted"></p></form>`;$('#answer-form').onsubmit=e=>{e.preventDefault();if(!$('#answer').value.trim()||x.done)return;finish(accepts(s,item.t,$('#answer').value),s,item)};$('#hint').onclick=()=>{x.hint=true;$('#hint-text').textContent='Beginnt mit „'+(item.t==='en'?s.en:s.codes[0])[0]+'“.';$('#answer').focus()};requestAnimationFrame(()=>$('#answer')?.focus({preventScroll:true}));}
 if(x.method==='flash'){answerArea.innerHTML='<div class="study-actions"><button id="reveal" class="primary">Antwort aufdecken</button></div>';$('#reveal').onclick=()=>{answerArea.innerHTML=`<p class="english">${esc(s.en)}</p><p class="code">${esc(s.codes[0])}</p><div class="actions study-actions"><button id="no">Nicht gewusst</button><button id="yes" class="primary">Gewusst</button></div>`;$('#no').onclick=()=>finish(false,s,item);$('#yes').onclick=()=>finish(true,s,item)}}
 if(x.method==='mc'){let value=b=>item.t==='en'?b.en:b.codes[0],correct=value(s);let pool=birds.filter(b=>b.id!==s.id&&!accepts(s,item.t,value(b))).map(b=>({b,r:Math.random()})).sort((a,b)=>+(b.b.group===s.group)-+(a.b.group===s.group)||a.r-b.r);let answers=[correct];for(let {b}of pool)if(!answers.includes(value(b))&&answers.length<4)answers.push(value(b));answers=answers.map(v=>({v,r:Math.random()})).sort((a,b)=>a.r-b.r).map(x=>x.v);answerArea.innerHTML='<div class="choices">'+answers.map((v,i)=>`<button data-choice="${i}">${esc(v)}</button>`).join('')+'</div>';document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>finish(accepts(s,item.t,answers[+b.dataset.choice]),s,item));}
}
async function finish(correct,s,item){let x=session;if(x.done)return;x.done=true;x.answered++;x.correct+=+correct;records[key(s,item.t)]=review(progress(s,item.t),correct,Date.now(),x.hint);if(!correct&&item.retry<2){let retry={...item,retry:item.retry+1};x.queue.splice(Math.min(x.index+4,x.queue.length),0,retry);}document.activeElement?.blur();$('#answer-area').replaceChildren();window.scrollTo(0,0);$('#feedback').innerHTML=`<div class="feedback"><strong class="${correct?'good':'bad'}">${correct?'Richtig.':'Noch nicht richtig.'}</strong><p>${esc(s.en)} · <span class="code">${esc(s.codes[0])}</span></p><p class="latin">${esc(s.sci)}</p>${s.codes.length>1?`<p>Auch akzeptiert: ${s.codes.slice(1).map(esc).join(', ')}</p>`:''}${x.photos?photoMarkup(s,true):''}<p class="muted">${correct&&!x.hint?'Nächste Wiederholung in '+records[key(s,item.t)].interval+' Tagen.':'Wiederholung in zehn Minuten.'}${!correct&&item.retry<2?' Die Art kommt in dieser Einheit erneut (höchstens zweimal).':''}</p><div class="study-actions"><button id="next" class="primary">Weiter →</button></div></div>`;if(x.photos)mountStudyPhoto(s);$('#next').onclick=()=>{x.index++;renderQuestion()};$('#next').focus({preventScroll:true});await save();if(!storageOK)$('#feedback').insertAdjacentHTML('beforeend',storageNotice());}
function stats(){session=null;let ps=Object.values(records),attempts=ps.reduce((a,p)=>a+p.attempts,0),correct=ps.reduce((a,p)=>a+p.correct,0),learned=birds.filter(s=>progress(s,'en')||progress(s,'code')).length,counts=t=>birds.filter(s=>mastered(progress(s,t))).length;let hard=birds.map(s=>({s,n:['en','code'].reduce((n,t)=>n+(progress(s,t)?.lapses||0),0)})).filter(x=>x.n).sort((a,b)=>b.n-a.n).slice(0,10);app.innerHTML=`<h1>Lernstand</h1>${storageNotice()}<div class="stats">${[[learned,'Arten begonnen'],[counts('en'),'Englische Namen beherrscht'],[counts('code'),'Codes beherrscht'],[ps.filter(p=>due(p)).length,'Lernziele jetzt fällig']].map(([n,l])=>`<div class="panel"><div class="number">${n}</div><span class="muted">${l}</span></div>`).join('')}</div><p>${attempts?Math.round(correct/attempts*100)+' % Erfolgsquote bei '+attempts+' Antworten.':'Noch keine Antworten. Starte eine erste Lerneinheit.'}</p><details class="panel group-details"><summary>Fortschritt nach Artengruppe</summary><p class="muted">Beherrschte Arten / Arten der Gruppe</p><table><thead><tr><th>Gruppe</th><th>Englisch</th><th>Codes</th></tr></thead><tbody>${groups().map(g=>{let a=birds.filter(s=>s.group===g);return `<tr><td>${esc(g)}</td><td>${a.filter(s=>mastered(progress(s,'en'))).length} / ${a.length}</td><td>${a.filter(s=>mastered(progress(s,'code'))).length} / ${a.length}</td></tr>`}).join('')}</tbody></table></details>${hard.length?`<section class="panel"><h2>Häufig falsch beantwortet</h2>${hard.map(({s,n})=>`<p>${esc(s.de)} <span class="muted">· ${n} Fehler</span></p>`).join('')}</section>`:''}<details class="panel group-details"><summary>Sichern, importieren oder zurücksetzen</summary><p>Ein Import ersetzt nach Bestätigung den aktuellen Lernstand in diesem Browser.</p><div class="toolbar"><button id="export">JSON exportieren</button><label for="import" class="sr">Lernstand importieren</label><input type="file" id="import" accept=".json,application/json"><button id="reset">Fortschritt zurücksetzen</button></div><p id="import-status" role="status"></p></details>`;$('#export').onclick=()=>{let blob=new Blob([JSON.stringify({app:'BirdNames DE',version:1,taxonomy:meta.taxonomy,exported:new Date().toISOString(),records},null,2)],{type:'application/json'});let u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='birdnames-de-lernstand.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};$('#import').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>5000000)throw Error('Datei ist zu groß (maximal 5 MB).');let r=validProgress(JSON.parse(await f.text()),new Set(birds.map(s=>s.id)));if(!confirm(Object.keys(r).length+' Lernwerte importieren und den aktuellen Stand ersetzen?'))return;records=r;await save();stats();$('#import-status').textContent='Lernstand importiert.';}catch(err){$('#import-status').textContent='Import fehlgeschlagen: '+err.message}};$('#reset').onclick=async()=>{if(confirm('Den gesamten Lernfortschritt in diesem Browser unwiderruflich löschen?')){records={};await save();stats()}};}
function info(){app.innerHTML=`<h1>Daten & Datenschutz</h1><div class="panel"><p class="data-count"><strong>${birds.length} Arten</strong> · eBird/Clements ${meta.taxonomy}</p><p>${esc(meta.selection)}</p><p>Lernstufen: ${levels.map((l,i)=>l+' '+birds.filter(s=>s.level===i+1).length).join(' · ')}. Diese redaktionellen Lernstufen sind keine Häufigkeits- oder Gefährdungskategorien.</p><h2>Namen und Codes</h2><p>Englische Hauptnamen, wissenschaftliche Namen, deutsche Namen, Arten-IDs und Quick Codes stammen aus der offiziellen eBird-Taxonomie. Verwendet wird das englische US-Hauptnamenset, nicht das britische Namenset.</p><p>Quick Find Codes sind vierstellige Eingabekürzel. Sie sind keine eindeutigen Arten-IDs. Mehrere Arten können denselben Code tragen; die Suche zeigt alle Treffer. Weitere offizielle englische Quick Codes werden bei der Eingabe akzeptiert. Bei einigen Arten führt die offizielle Tabelle keinen separaten common-name Quick Code, sondern nur einen Banding Code als eBird-Eingabekürzel (zum Beispiel MALL für Mallard). Diese Übernahme ist im Artdetail ausdrücklich gekennzeichnet. Wissenschaftliche Quick Codes werden hier nicht verwendet.</p><p>Beispiel Amsel: Der eBird-Hauptname ist „Eurasian Blackbird“ (EUBL); „Common Blackbird“ und COBL werden ebenfalls akzeptiert. Die Schreibweise wird aus der offiziellen Tabelle übernommen; kein Code wird für diese App errechnet.</p><h2>Quellen & Stand</h2><ul>${meta.sources.map(s=>`<li><a target="_blank" rel="noopener" href="${esc(s.url)}">${esc(s.title)}</a></li>`).join('')}</ul><p>Aufbereitung: ${esc(meta.built)}. Die Datei mit Namensübersetzungen hat den Stand 30.10.2025; Abgleich mit der offiziellen eBird-Taxonomie v2025-4 (April 2026). ${esc(meta.validation)}</p><p>Vorkommensstatus sind bewusst grob: Brutvogelstatus nach DDA-Bericht 2025 (Berichtsperiode 2017–2022 mit dokumentierten Aktualisierungen). Rastvogel bedeutet Nutzung Deutschlands außerhalb der Brutzeit; daraus wird nicht pauschal ein Winterstatus abgeleitet. Sonderfälle und taxonomische Zusammenfassungen sind bei der Art vermerkt.</p><h2>So wird wiederholt</h2><p>Ohne Hinweis richtig: 1, 3, 7, 14, 30, 60 Tage. Falsch oder mit Hinweis: zehn Minuten; die Erfolgsserie beginnt neu. Drei richtige Antworten ohne Hinweis in Folge gelten als beherrscht. Fehler werden nach möglichst drei weiteren Fragen erneut vorgelegt, bei kurzen Einheiten früher; höchstens zweimal je Lernziel und Einheit. Die Statistik zählt auch diese Wiederholungen.</p><h2>Artenbilder</h2><p>Die optionalen Artenbilder stammen aus Wikimedia Commons. Für jede Art ist ein Foto mit Fotografenangabe, Link zur Originaldatei und der jeweiligen Lizenz hinterlegt. Unter „Bildnachweis“ steht der vollständige Bildtitel. Die verkleinerten Bilddateien werden zusammen mit dieser App ausgeliefert. Die Bildlizenzen gelten jeweils für das zugehörige Foto.</p><p>Im Nachschlagemodus erscheinen Fotos direkt in den Artenkacheln, sobald „Artenbilder“ aktiviert ist. Im Lernmodus erscheinen sie erst nach der Bewertung einer Antwort. Kann ein Bild nicht geladen werden, führt ein Link zur artbezogenen eBird-Fotogalerie.</p><p><a href="https://commons.wikimedia.org/wiki/Commons:Reusing_content_outside_Wikimedia" target="_blank" rel="noopener noreferrer">Wikimedia Commons: Bildnutzung und Lizenzen</a> · <a href="photos.json" download>Vollständige Bildnachweise als JSON</a></p><h2>Datenschutz & Grenzen</h2><p>Die App verwendet IndexedDB für Lernstände und lokale Browser-Speicherung für das Farbschema. Keine Anmeldung, keine zentrale Lerndatenbank, keine eingebundenen Analytics, externen Schriftarten oder Tracking-Dienste. Der Hostinganbieter verarbeitet technisch notwendige Zugriffsdaten. Die Fotos werden vom gleichen Hostinganbieter wie die App geladen; dafür ist keine Verbindung zu Wikimedia oder Cornell erforderlich. Im Lernmodus werden die Bilder der aktuellen und der nächsten beiden Fragen im Hintergrund vorbereitet und bereits geladene Bilder im Browser zwischengespeichert. Dieser Bildcache kann wie andere Websitedaten vom Browser gelöscht werden. Externe Seiten öffnen erst beim Anklicken der Quellen-, Lizenz- oder Galerielinks.</p><p>Private Browserfenster, gelöschte Websitedaten und Browserbereinigung können den Lernstand entfernen. Sichere ihn regelmäßig per JSON. Kein geräteübergreifender Abgleich. Offline-Nutzung ist in dieser Version nicht zugesichert.</p><p>Diese App ist ein unabhängiges Lernangebot und kein Produkt des Cornell Lab oder des DDA. Die Artenauswahl ist ein Lernbestand, keine vollständige nationale Nachweisliste.</p><a href="species.json" download>Artenstammdaten als JSON</a> · <a href="validation.json">Validierungsbericht</a></div>`;}
function route(){studyMode(false);let page=location.hash.slice(1)||'nachschlagen';document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.hash==='#'+page);if(a.hash==='#'+page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});({nachschlagen:lookup,lernen:learn,statistik:stats,info}[page]||lookup)();window.scrollTo(0,0)}
try{let data=await(await fetch('species.json')).json();birds=data.species.sort((a,b)=>a.de.localeCompare(b.de,'de'));meta=data.meta;try{photos=(await(await fetch('photos.json')).json()).photos}catch(err){console.warn('Artenbilder nicht geladen',err)}try{await initDB()}catch{storageOK=false}window.addEventListener('hashchange',route);route();}catch(err){app.innerHTML='<h1>Daten konnten nicht geladen werden.</h1><p>Bitte Seite erneut laden.</p>';console.error(err)}
